-- Datos migrados desde MySQL `bd_registro`
BEGIN;








SELECT setval(pg_get_serial_sequence('admin', 'id'), COALESCE((SELECT MAX(id) FROM admin), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('usuarios', 'id'), COALESCE((SELECT MAX(id) FROM usuarios), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('productos', 'id'), COALESCE((SELECT MAX(id) FROM productos), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('proveedores', 'id'), COALESCE((SELECT MAX(id) FROM proveedores), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('compras_proveedores', 'id'), COALESCE((SELECT MAX(id) FROM compras_proveedores), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('historial_admin', 'id'), COALESCE((SELECT MAX(id) FROM historial_admin), 0) + 1, false);
SELECT setval(pg_get_serial_sequence('historial_compras', 'id'), COALESCE((SELECT MAX(id) FROM historial_compras), 0) + 1, false);
COMMIT;
